void setup() {
  Serial.begin(9600);          // инициализация последовательного порта
  pinMode(LED_BUILTIN, OUTPUT); // встроенный светодиод как выход
}

void loop() {
  digitalWrite(LED_BUILTIN, HIGH);  // включить светодиод
  Serial.println("LED ON");         // отправить сообщение в монитор порта
  delay(1000);                      // подождать 1 секунду
  digitalWrite(LED_BUILTIN, LOW);   // выключить светодиод
  Serial.println("LED OFF");
  delay(1000);
}
